use glob_match::glob_match;
use std::path::Path;

/// Check if a file path matches any of the given gitignore-style glob patterns.
pub fn matches_ignore_patterns(path: &str, patterns: &[String]) -> bool {
    for pattern in patterns {
        let pat = pattern.trim();
        if pat.is_empty() || pat.starts_with('#') {
            continue;
        }
        // Check both the full path and the basename
        let basename = Path::new(path)
            .file_name()
            .and_then(|s| s.to_str())
            .unwrap_or(path);
        // Also try matching with a leading **/ for nested matching
        if glob_match(pat, path)
            || glob_match(pat, basename)
            || glob_match(&format!("**/{}", pat), path)
        {
            return true;
        }
    }
    false
}

/// Read gitignore-style patterns from a file and return a list of patterns.
pub fn read_ignore_file(path: &Path) -> std::io::Result<Vec<String>> {
    let content = std::fs::read_to_string(path)?;
    Ok(content
        .lines()
        .map(|l| l.trim().to_string())
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .collect())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_glob_match() {
        let patterns = vec!["*.log".to_string()];
        assert!(matches_ignore_patterns("error.log", &patterns));
        assert!(matches_ignore_patterns("dir/error.log", &patterns));
        assert!(!matches_ignore_patterns("main.js", &patterns));
    }

    #[test]
    fn test_dir_pattern() {
        let patterns = vec!["node_modules/".to_string()];
        assert!(matches_ignore_patterns("node_modules/foo.js", &patterns));
        assert!(!matches_ignore_patterns("src/node_modules/foo.js", &patterns));
    }

    #[test]
    fn test_negated_pattern() {
        let patterns = vec!["*.log".to_string()];
        assert!(matches_ignore_patterns("debug.log", &patterns));
    }

    #[test]
    fn test_empty_pattern() {
        let patterns: Vec<String> = vec![];
        assert!(!matches_ignore_patterns("foo.js", &patterns));
    }
}"}

