use clap::Parser;
use std::path::PathBuf;

#[derive(Parser, Debug, Clone)]
#[command(
    name = "jscodeshift",
    version,
    about = "A toolkit for JavaScript codemods",
    disable_help_flag = true,
    disable_version_flag = true,
    trailing_var_arg = true
)]
pub struct Options {
    /// path to the transform file. Can be either a local path or url
    #[arg(short = 't', long = "transform", value_name = "FILE", default_value = "./transform.js")]
    pub transform: String,

    /// start at most N child processes to process source files (default: max(all - 1, 1))
    #[arg(short = 'c', long = "cpus", value_name = "N")]
    pub cpus: Option<usize>,

    /// show more information about the transform process
    #[arg(short = 'v', long = "verbose", value_name = "N", default_value = "0", value_parser = clap::value_parser!(u8).range(0..=2))]
    pub verbose: u8,

    /// dry run (no changes are made to files)
    #[arg(short = 'd', long = "dry")]
    pub dry: bool,

    /// print transformed files to stdout, useful for development
    #[arg(short = 'p', long = "print")]
    pub print: bool,

    /// apply babeljs to the transform file
    #[arg(long = "babel", overrides_with = "no_babel", default_value = "true")]
    pub babel: bool,

    /// do not apply babeljs to the transform file
    #[arg(long = "no-babel", overrides_with = "babel")]
    pub no_babel: bool,

    /// transform files with these file extensions (comma separated list)
    #[arg(long = "extensions", value_name = "EXT")]
    pub extensions: Option<String>,

    /// ignore files that match a provided glob expression
    #[arg(long = "ignore-pattern", value_name = "GLOB")]
    pub ignore_pattern: Vec<String>,

    /// ignore files if they match patterns sourced from a configuration file (e.g. a .gitignore)
    #[arg(long = "ignore-config", value_name = "FILE")]
    pub ignore_config: Vec<String>,

    /// adds entries the current directory's .gitignore file
    #[arg(long = "gitignore")]
    pub gitignore: bool,

    /// run serially in the current process
    #[arg(long = "run-in-band")]
    pub run_in_band: bool,

    /// do not write to stdout or stderr
    #[arg(short = 's', long = "silent")]
    pub silent: bool,

    /// the parser to use for parsing the source files
    #[arg(long = "parser", value_name = "PARSER", default_value = "babel")]
    pub parser: String,

    /// path to a JSON file containing a custom parser configuration for flow or babylon
    #[arg(long = "parser-config", value_name = "FILE")]
    pub parser_config: Option<PathBuf>,

    /// Return a non-zero code when there are errors
    #[arg(long = "fail-on-error")]
    pub fail_on_error: bool,

    /// print version and exit
    #[arg(long = "version")]
    pub version: bool,

    /// read file/directory list from stdin
    #[arg(long = "stdin")]
    pub stdin: bool,

    /// print this help and exit
    #[arg(short = 'h', long = "help")]
    pub help: bool,

    /// Files or directories to transform
    #[arg(value_name = "FILES", default_value = ".", allow_hyphen_values = true)]
    pub files: Vec<String>,
}

pub fn parse() -> Options {
    Options::parse()
}

/// Collect unknown `--key=value` or `--key value` pairs from raw args
/// These are passed through to the transform as custom options.
pub fn collect_extra_options() -> Vec<(String, String)> {
    let args: Vec<String> = std::env::args().collect();
    let known_flags = [
        "transform", "t", "cpus", "c", "verbose", "v", "dry", "d",
        "print", "p", "babel", "no-babel", "extensions",
        "ignore-pattern", "ignore-config", "gitignore", "run-in-band",
        "silent", "s", "parser", "parser-config", "fail-on-error",
        "version", "stdin", "help", "h",
    ];
    let mut extras = Vec::new();
    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        if let Some(stripped) = arg.strip_prefix("--") {
            if let Some(eq_pos) = stripped.find('=') {
                let key = &stripped[..eq_pos];
                if !known_flags.contains(&key) {
                    let val = stripped[eq_pos + 1..].to_string();
                    extras.push((key.to_string(), val));
                }
            } else if !known_flags.contains(&stripped.as_ref()) {
                // Check next arg for value
                if i + 1 < args.len() && !args[i + 1].starts_with('-') {
                    extras.push((stripped.to_string(), args[i + 1].clone()));
                    i += 1;
                } else {
                    extras.push((stripped.to_string(), "true".to_string()));
                }
            }
        }
        i += 1;
    }
    extras
}"}

{"command": "create", "path": "/workspace/codebase/src/runner.rs", "file_text": "// Copyright (c) Facebook, Inc. and its affiliates.
//
// This source code is licensed under the MIT license found in the
// LICENSE file in the root directory of this source tree.

use crate::args::{collect_extra_options, Options};
use crate::ignore_files;
use owo_colors::{OwoColorize, Stream::Stdout};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::io::{BufRead, BufReader, Write};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::time::Instant;

const DEFAULT_EXTENSIONS: &str = "cjs,cts,es,es6,js,jsx,mjs,mts,ts,tsx";
const CHUNK_SIZE: usize = 50;

#[derive(Serialize, Deserialize, Debug, Clone)]
pub struct TransformOptions {
    pub parser: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub parser_config: Option<String>,
    pub print: bool,
    pub dry: bool,
    #[serde(flatten)]
    pub extra: HashMap<String, serde_json::Value>,
}

#[derive(Serialize, Debug)]
struct WorkerInput {
    files: Vec<String>,
    options: TransformOptions,
}

#[derive(Deserialize, Debug)]
struct WorkerMessage {
    action: String,
    #[serde(default)]
    status: String,
    #[serde(default)]
    msg: String,
    #[serde(default)]
    name: String,
    #[serde(default)]
    quantity: u64,
    #[serde(default)]
    file: String,
    #[serde(default)]
    output: String,
}

fn line_break(s: &str) -> String {
    if s.ends_with('\n') {
        s.to_string()
    } else {
        format!("{}\n", s)
    }
}

fn discover_files(paths: &[String], extensions: &[String]) -> Vec<String> {
    let mut files = Vec::new();
    for raw_path in paths {
        let p = Path::new(raw_path);
        if !p.exists() {
            eprintln!("Skipping path {} which does not exist.", raw_path);
            continue;
        }
        if p.is_dir() {
            collect_dir_files(p, &mut files);
        } else {
            files.push(p.to_string_lossy().to_string());
        }
    }
    // Filter by extension
    if !extensions.is_empty() {
        files.retain(|f| {
            Path::new(f)
                .extension()
                .and_then(|e| e.to_str())
                .map(|e| extensions.iter().any(|ext| ext == e))
                .unwrap_or(false)
        });
    }
    files
}

fn collect_dir_files(dir: &Path, out: &mut Vec<String>) {
    if let Ok(entries) = std::fs::read_dir(dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            let path_str = path.to_string_lossy().to_string();
            if ignore_files::should_ignore(&path_str) {
                continue;
            }
            if path.is_dir() {
                collect_dir_files(&path, out);
            } else {
                out.push(path_str);
            }
        }
    }
}

fn extension_list(ext_arg: Option<&str>) -> Vec<String> {
    let raw = ext_arg.unwrap_or(DEFAULT_EXTENSIONS);
    raw.split(',')
        .map(|e| {
            let e = e.trim();
            if let Some(stripped) = e.strip_prefix('.') {
                stripped.to_string()
            } else {
                e.to_string()
            }
        })
        .filter(|e| !e.is_empty())
        .collect()
}

pub fn run(opts: &Options) -> i32 {
    if opts.help {
        print_help();
        return 0;
    }
    if opts.version {
        print_version();
        return 0;
    }

    let extensions = extension_list(opts.extensions.as_deref());

    // Setup ignore patterns
    for pat in &opts.ignore_pattern {
        ignore_files::add_pattern(pat);
    }
    for file in &opts.ignore_config {
        if let Ok(patterns) = ignore_files::read_ignore_file(Path::new(file)) {
            for p in &patterns {
                ignore_files::add_pattern(p);
            }
        }
    }
    if opts.gitignore {
        let cwd = std::env::current_dir().unwrap_or_default();
        let gitignore_path = cwd.join(".gitignore");
        if let Ok(patterns) = ignore_files::read_ignore_file(&gitignore_path) {
            for p in &patterns {
                ignore_files::add_pattern(&p);
            }
        }
    }

    let transform = &opts.transform;
    let paths: Vec<String> = if opts.files.is_empty() || (opts.files.len() == 1 && opts.files[0] == ".") {
        vec![".".to_string()]
    } else {
        opts.files.clone()
    };

    // Handle URL transform
    let transform_path = if transform.starts_with("http://") || transform.starts_with("https://") {
        match download_transform(transform) {
            Ok(p) => p,
            Err(e) => {
                eprintln!("{}", e);
                return 1;
            }
        }
    } else if !Path::new(transform).exists() {
        eprintln!(
            "{}{}",
            " ERROR ".on_red().white(),
            format!(" Transform file {} does not exist \n", transform)
        );
        return 1;
    } else {
        PathBuf::from(std::path::absolute(transform).unwrap_or_else(|_| PathBuf::from(transform)))
    };

    let files = discover_files(&paths, &extensions);

    if files.is_empty() {
        println!("No files selected, nothing to do.");
        return 0;
    }

    let available_cpus = std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(1);
    let default_cpus = std::cmp::max(available_cpus.saturating_sub(1), 1);
    let cpus = opts.cpus.map(|c| std::cmp::min(c, default_cpus)).unwrap_or(default_cpus);

    let num_files = files.len();
    let num_workers = if opts.run_in_band {
        1
    } else {
        std::cmp::min(num_files, cpus)
    };
    let chunk_size = if num_workers > 1 {
        std::cmp::min((num_files + num_workers - 1) / num_workers, CHUNK_SIZE)
    } else {
        num_files
    };

    if !opts.silent {
        println!("Processing {} files...", num_files);
        if !opts.run_in_band {
            println!("Spawning {} workers...", num_workers);
        }
        if opts.dry {
            println!("{}", "Running in dry mode, no files will be written!".green());
        }
    }

    // Build extra options for the transform
    let extra_options: HashMap<String, serde_json::Value> = collect_extra_options()
        .into_iter()
        .map(|(k, v)| {
            let val = serde_json::from_str(&v).unwrap_or(serde_json::Value::String(v));
            (k, val)
        })
        .collect();

    let babel_flag = if opts.no_babel { "no-babel" } else { "babel" };

    let transform_opts = TransformOptions {
        parser: Some(opts.parser.clone()),
        parser_config: opts.parser_config.as_ref().map(|p| p.to_string_lossy().to_string()),
        print: opts.print,
        dry: opts.dry,
        extra: extra_options,
    };

    let mut file_counters: HashMap<String, u64> =
        [("error", 0), ("ok", 0), ("nochange", 0), ("skip", 0)]
            .iter()
            .map(|(k, v)| (k.to_string(), *v))
            .collect();
    let mut stats_counter: HashMap<String, u64> = HashMap::new();
    let start_time = Instant::now();

    // Find the Node.js bridge script
    let bridge_script = find_bridge_script();

    // Prepare file chunks
    let chunks: Vec<Vec<String>> = files
        .chunks(chunk_size)
        .map(|c| c.to_vec())
        .collect();
    let mut chunk_iter = chunks.into_iter();

    // Spawn workers and distribute initial chunks
    let mut workers: Vec<std::process::Child> = Vec::new();
    let mut worker_stdins: Vec<std::process::ChildStdin> = Vec::new();
    let mut worker_states: Vec<Option<BufReader<std::process::ChildStdout>>> = Vec::new();

    for _ in 0..num_workers {
        let mut child = Command::new("node")
            .arg(&bridge_script)
            .arg(transform_path.to_string_lossy().to_string())
            .arg(babel_flag)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .spawn()
            .expect("Failed to spawn worker");

        let stdin = child.stdin.take().unwrap();
        let stdout = child.stdout.take().unwrap();

        // Send initial chunk
        let batch = chunk_iter.next().unwrap_or_default();
        send_batch(&mut stdin, &batch, &transform_opts);

        workers.push(child);
        worker_stdins.push(stdin);
        worker_states.push(Some(BufReader::new(stdout)));
    }

    // Process worker messages
