fn print_version() {
    // To match the original behavior, call node to get versions
    let output = Command::new("node")
        .args([
            "-e",
            r#"
const pkg = require('./package.json');
const requirePackage = require('./utils/requirePackage');
console.log([
  `jscodeshift: ${pkg.version}`,
  ` - babel: ${require('@babel/core').version}`,
  ` - babylon: ${requirePackage('@babel/parser').version}`,
  ` - flow: ${requirePackage('flow-parser').version}`,
  ` - recast: ${requirePackage('recast').version}`,
].join('\n'));
"#,
        ])
        .output();
    match output {
        Ok(o) if o.status.success() => {
            println!("{}", String::from_utf8_lossy(&o.stdout));
        }
        _ => {
            // Fallback
            println!("jscodeshift: {}", env!("CARGO_PKG_VERSION"));
        }
    }
}

fn download_transform(url: &str) -> Result<PathBuf, String> {
    let ext = Path::new(url)
        .extension()
        .map(|e| format!(".{}", e.to_string_lossy()))
        .unwrap_or_default();
    let tmp = tempfile::Builder::new()
        .prefix("jscodeshift")
        .suffix(&ext)
        .tempfile()
        .map_err(|e| format!("Failed to create temp file: {}", e))?;
    let tmp_path = tmp.path().to_path_buf();
    let client = reqwest::blocking::Client::new();
    let resp = client
        .get(url)
        .send()
        .map_err(|e| format!("Failed to download {}: {}", url, e))?;
    let bytes = resp
        .bytes()
        .map_err(|e| format!("Failed to read response: {}", e))?;
    std::fs::write(&tmp_path, &bytes).map_err(|e| format!("Failed to write temp file: {}", e))?;
    Ok(tmp_path)
}"}

