use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::io::{BufRead, BufReader, Write};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::time::Instant;

const DEFAULT_EXTENSIONS: &str = "cjs,cts,es,es6,js,jsx,mjs,mts,ts,tsx";
const CHUNK_SIZE: usize = 50;

#[derive(Serialize, Deserialize, Debug, Clone)]
pub struct TransformOptions {
    pub parser: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub parser_config: Option<String>,
    pub print: bool,
    pub dry: bool,
    #[serde(flatten)]
    pub extra: HashMap<String, serde_json::Value>,
}

#[derive(Serialize, Debug)]
struct WorkerInput {
    files: Vec<String>,
    options: TransformOptions,
}

#[derive(Deserialize, Debug)]
struct WorkerMessage {
    action: String,
    #[serde(default)]
    status: String,
    #[serde(default)]
    msg: String,
    #[serde(default)]
    name: String,
    #[serde(default)]
    quantity: u64,
    #[serde(default)]
    file: String,
}

fn discover_files(paths: &[String], extensions: &[String]) -> Vec<String> {
    let mut files = Vec::new();
    for raw_path in paths {
        let p = Path::new(raw_path);
        if !p.exists() {
            eprintln!("Skipping path {} which does not exist.", raw_path);
            continue;
        }
        if p.is_dir() {
            collect_dir_files(p, &mut files);
        } else {
            files.push(p.to_string_lossy().to_string());
        }
    }
    if !extensions.is_empty() {
        files.retain(|f| {
            Path::new(f)
                .extension()
                .and_then(|e| e.to_str())
                .map(|e| extensions.iter().any(|ext| ext == e))
                .unwrap_or(false)
        });
    }
    files
}

fn collect_dir_files(dir: &Path, out: &mut Vec<String>) {
    if let Ok(entries) = std::fs::read_dir(dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            let path_str = path.to_string_lossy().to_string();
            if ignore_files::should_ignore(&path_str) {
                continue;
            }
            if path.is_dir() {
                collect_dir_files(&path, out);
            } else {
                out.push(path_str);
            }
        }
    }
}

fn extension_list(ext_arg: Option<&str>) -> Vec<String> {
    let raw = ext_arg.unwrap_or(DEFAULT_EXTENSIONS);
    raw.split(',')
        .map(|e| {
            let e = e.trim();
            if let Some(stripped) = e.strip_prefix('.') {
                stripped.to_string()
            } else {
                e.to_string()
            }
        })
        .filter(|e| !e.is_empty())
        .collect()
}

pub fn run(opts: &Options) -> i32 {
    if opts.help {
        print_help();
        return 0;
    }
    if opts.version {
        print_version();
        return 0;
    }

    let extensions = extension_list(opts.extensions.as_deref());

    // Setup ignore patterns
    for pat in &opts.ignore_pattern {
        ignore_files::add_pattern(pat);
    }
    for file in &opts.ignore_config {
        if let Ok(patterns) = ignore_files::read_ignore_file(Path::new(file)) {
            for p in &patterns {
                ignore_files::add_pattern(&p);
            }
        }
    }
    if opts.gitignore {
        let cwd = std::env::current_dir().unwrap_or_default();
        let gitignore_path = cwd.join(".gitignore");
        if let Ok(patterns) = ignore_files::read_ignore_file(&gitignore_path) {
            for p in &patterns {
                ignore_files::add_pattern(&p);
            }
        }
    }

    let transform = &opts.transform;
    let paths: Vec<String> = if opts.files.is_empty() || (opts.files.len() == 1 && opts.files[0] == ".") {
        vec![".".to_string()]
    } else {
        opts.files.clone()
    };

    let transform_path = if transform.starts_with("http://") || transform.starts_with("https://") {
        match download_transform(transform) {
            Ok(p) => p,
            Err(e) => {
                eprintln!("{}", e);
                return 1;
            }
        }
    } else if !Path::new(transform).exists() {
        eprintln!(
            "{} Transform file {} does not exist",
            "ERROR".on_red().white(),
            transform
        );
        return 1;
    } else {
        std::path::absolute(transform).unwrap_or_else(|_| PathBuf::from(transform))
    };

    let files = discover_files(&paths, &extensions);

    if files.is_empty() {
        println!("No files selected, nothing to do.");
        return 0;
    }

    let available_cpus = std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(1);
    let default_cpus = std::cmp::max(available_cpus.saturating_sub(1), 1);
    let cpus = opts
        .cpus
        .map(|c| std::cmp::min(c, default_cpus))
        .unwrap_or(default_cpus);

    let num_files = files.len();
    let num_workers = if opts.run_in_band {
        1
    } else {
        std::cmp::min(num_files, cpus)
    };
    let chunk_size = if num_workers > 1 {
        std::cmp::min(
            (num_files + num_workers - 1) / num_workers,
            CHUNK_SIZE,
        )
    } else {
        num_files
    };

    if !opts.silent {
        println!("Processing {} files...", num_files);
        if !opts.run_in_band {
            println!("Spawning {} workers...", num_workers);
        }
        if opts.dry {
            println!(
                "{}",
                "Running in dry mode, no files will be written!"
                    .green()
            );
        }
    }

    let extra_options: HashMap<String, serde_json::Value> = collect_extra_options()
        .into_iter()
        .map(|(k, v)| {
            let val = serde_json::from_str(&v).unwrap_or(serde_json::Value::String(v));
            (k, val)
        })
        .collect();

    let babel_flag = if opts.no_babel {
        "no-babel"
    } else {
        "babel"
    };

    let reader_config: Option<String> = opts.parser_config.as_ref().map(|p| {
        std::fs::read_to_string(p).unwrap_or_default()
    });

    let transform_opts = TransformOptions {
        parser: Some(opts.parser.clone()),
        parser_config: reader_config,
        print: opts.print,
        dry: opts.dry,
        extra: extra_options,
    };

    let mut file_counters: HashMap<String, u64> = [
        ("error", 0),
        ("ok", 0),
        ("nochange", 0),
        ("skip", 0),
    ]
    .iter()
    .map(|(k, v)| (k.to_string(), *v))
    .collect();
    let mut stats_counter: HashMap<String, u64> = HashMap::new();
    let start_time = Instant::now();

    let bridge_script = find_bridge_script();

    let chunks: Vec<Vec<String>> = files.chunks(chunk_size).map(|c| c.to_vec()).collect();
    let mut chunk_iter = chunks.into_iter();

    struct Worker {
        child: std::process::Child,
        stdin: std::process::ChildStdin,
        stdout: BufReader<std::process::ChildStdout>,
    }

    let mut workers: Vec<Worker> = Vec::new();
    for _ in 0..num_workers {
        let mut child = Command::new("node")
            .arg(bridge_script.to_string_lossy().to_string())
            .arg(transform_path.to_string_lossy().to_string())
            .arg(babel_flag)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .spawn()
