        let stdout = child.stdout.take().unwrap();

        let mut worker = Worker {
            child,
            stdin,
            stdout: BufReader::new(stdout),
        };

        let batch = chunk_iter.next().unwrap_or_default();
        send_batch(&mut worker.stdin, &batch, &transform_opts);

        workers.push(worker);
    }

    // Main event loop: read from workers, dispatch messages, refill chunks
    let mut active = true;
    while active {
        active = false;
        for worker in &mut workers {
            let mut line = String::new();
            match worker.stdout.read_line(&mut line) {
                Ok(0) => {
                    // EOF - this worker is done
                    continue;
                }
                Ok(_) => {
                    active = true;
                    let line = line.trim().to_string();
                    if line.is_empty() {
                        continue;
                    }
                    if let Ok(msg) = serde_json::from_str::<WorkerMessage>(&line) {
                        match msg.action.as_str() {
                            "status" => {
                                *file_counters
                                    .entry(msg.status.clone())
                                    .or_insert(0) += 1;

                                let show = match msg.status.as_str() {
                                    "ok" => opts.verbose >= 2,
                                    "nochange" | "skip" => opts.verbose >= 1,
                                    _ => true,
                                };
                                if show {
                                    let label = match msg.status.as_str() {
                                        "ok" => " OK ".on_green().white().to_string(),
                                        "nochange" => " NOC ".on_yellow().white().to_string(),
                                        "skip" => " SKIP ".on_yellow().white().to_string(),
                                        "error" => " ERR ".on_red().white().to_string(),
                                        _ => format!(" {} ", msg.status),
                                    };
                                    let suffix = if msg.msg.ends_with('\n') {
                                        msg.msg.clone()
                                    } else {
                                        format!("{}\n", msg.msg)
                                    };
                                    print!("{}{}", label, suffix);
                                }
                            }
                            "update" => {
                                *stats_counter
                                    .entry(msg.name.clone())
                                    .or_insert(0) += msg.quantity;
                            }
                            "report" => {
                                print!(
                                    "{}{}",
                                    " REP ".on_blue().white(),
                                    if msg.msg.ends_with('\n') {
                                        format!("{} {}", msg.file, msg.msg)
                                    } else {
                                        format!("{} {}\n", msg.file, msg.msg)
                                    }
                                );
                            }
                            "free" => {
                                if let Some(batch) = chunk_iter.next() {
                                    if !opts.silent && !opts.run_in_band {
                                        eprintln!(
                                            "Sending {} files to free worker...",
                                            batch.len()
                                        );
                                    }
                                    send_batch(
                                        &mut worker.stdin,
                                        &batch,
                                        &transform_opts,
                                    );
                                }
                                // If no more chunks, stdin will eventually close when the
                                // worker drops, which the Node bridge detects as EOF.
                            }
                            _ => {}
                        }
                    }
                }
                Err(_) => {
                    continue;
                }
            }
        }
    }

    // Wait for all children to exit
    for mut worker in workers {
        let _ = worker.child.wait();
    }

    let elapsed = start_time.elapsed();
    let time_elapsed = format!("{:.3}", elapsed.as_secs_f64());

    if !opts.silent {
        println!("All done.");
        show_file_stats(&file_counters);
        show_stats(&stats_counter);
        println!("Time elapsed: {}seconds", time_elapsed);

        if opts.fail_on_error && file_counters.get("error").copied().unwrap_or(0) > 0 {
            return 1;
        }
    }

    0
}

pub fn run_stdin(opts: &Options) -> Result<(), String> {
    let mut buffer = String::new();
    std::io::stdin()
        .read_to_string(&mut buffer)
        .map_err(|e| format!("Failed to read stdin: {}", e))?;
    let paths: Vec<String> = buffer
        .lines()
        .map(|l| l.trim().to_string())
        .filter(|l| !l.is_empty())
        .collect();
    let mut new_opts = opts.clone();
    new_opts.files = paths;
    run(&new_opts);
    Ok(())
}

fn send_batch(stdin: &mut impl Write, files: &[String], options: &TransformOptions) {
    let input = WorkerInput {
        files: files.to_vec(),
        options: options.clone(),
    };
    let json = serde_json::to_string(&input).unwrap_or_default();
    let _ = writeln!(stdin, "{}", json);
    let _ = stdin.flush();
}

fn find_bridge_script() -> PathBuf {
    let exe_path = std::env::current_exe().unwrap_or_default();
    let exe_dir = exe_path.parent().unwrap_or(Path::new("."));

    let candidates = [
        PathBuf::from("bridge/transform-host.js"),
        exe_dir.join("bridge/transform-host.js"),
        exe_dir.join("../bridge/transform-host.js"),
        exe_dir.join("../../bridge/transform-host.js"),
    ];
    for candidate in &candidates {
        if candidate.exists() {
            return candidate.clone();
        }
    }
    PathBuf::from("bridge/transform-host.js")
}

