//
// This source code is licensed under the MIT license found in the
// LICENSE file in the root directory of this source tree.

use glob_match::glob_match;
use std::path::Path;
use std::sync::Mutex;

static MATCHERS: Mutex<Vec<String>> = Mutex::new(Vec::new());

/// Add a gitignore-style glob pattern.
pub fn add_pattern(pattern: &str) {
    if pattern.is_empty() || pattern.starts_with('#') {
        return;
    }
    let mut matchers = MATCHERS.lock().unwrap();
    let p = pattern.to_string();
    if !p.contains('/') {
        matchers.push(format!("**/{}", p));
    } else if p.ends_with('/') {
        matchers.push(format!("**/{}**", p));
        matchers.push(format!("{}**", p));
    }
    matchers.push(p);
}

/// Check if a path should be ignored according to the current patterns.
pub fn should_ignore(path: &str) -> bool {
    let matchers = MATCHERS.lock().unwrap();
    if matchers.is_empty() {
        return false;
    }
    // Strip leading traversal prefixes like ./ or ../ for consistent matching.
    let normalized = path.trim_start_matches("./");
    let normalized = if normalized != path {
        normalized
    } else {
        path.trim_start_matches("../")
    };
    for pat in matchers.iter() {
        if glob_match(pat, path) || (normalized != path && glob_match(pat, normalized)) {
            return true;
        }
    }
    false
}

/// Read patterns from a gitignore-style file.
pub fn read_ignore_file(path: &Path) -> std::io::Result<Vec<String>> {
    let content = std::fs::read_to_string(path)?;
    Ok(content
        .lines()
        .map(|l| l.trim().to_string())
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .collect())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_glob_match() {
        add_pattern("*.log");
        assert!(should_ignore("error.log"));
        assert!(should_ignore("dir/error.log"));
        assert!(!should_ignore("main.js"));
    }

    #[test]
    fn test_dir_pattern() {
        // Reset
        {
            let mut m = MATCHERS.lock().unwrap();
            m.clear();
        }
        add_pattern("node_modules/");
        assert!(should_ignore("node_modules/foo.js"));
    }

    #[test]
    fn test_empty() {
        let mut m = MATCHERS.lock().unwrap();
        m.clear();
        drop(m);
        assert!(!should_ignore("foo.js"));
    }
}"}

