pub fn parse() -> (Options, Vec<(String, String)>) {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let mut opts = Options::default();
    opts.files.clear();

    let mut extras: Vec<(String, String)> = Vec::new();
    let mut i = 0;

    let is_known_long = |name: &str| -> bool {
        matches!(
            name,
            "transform" | "cpus" | "verbose" | "dry" | "print"
                | "babel" | "no-babel" | "extensions"
                | "ignore-pattern" | "ignore-config" | "gitignore"
                | "run-in-band" | "silent" | "parser" | "parser-config"
                | "fail-on-error" | "version" | "stdin" | "help"
        )
    };

    while i < args.len() {
        let arg = &args[i];

        if arg == "--" {
            // Everything after -- is a file path
            for a in &args[i + 1..] {
                opts.files.push(a.clone());
            }
            break;
        }

        if let Some(rest) = arg.strip_prefix("--") {
            if let Some(eq_pos) = rest.find('=') {
                let key = &rest[..eq_pos];
                let val = rest[eq_pos + 1..].to_string();
                match key {
                    "transform" => opts.transform = val,
                    "cpus" => opts.cpus = val.parse().ok(),
                    "verbose" => opts.verbose = val.parse().unwrap_or(0),
                    "extensions" => opts.extensions = Some(val),
                    "ignore-pattern" => opts.ignore_pattern.push(val),
                    "ignore-config" => opts.ignore_config.push(val),
                    "parser" => opts.parser = val,
                    "parser-config" => opts.parser_config = Some(PathBuf::from(val)),
                    _ => {
                        extras.push((key.to_string(), val));
                    }
                }
            } else {
                match rest {
                    "dry" => opts.dry = true,
                    "print" => opts.print = true,
                    "babel" => opts.babel = true,
                    "no-babel" => { opts.no_babel = true; opts.babel = false; }
                    "gitignore" => opts.gitignore = true,
                    "run-in-band" => opts.run_in_band = true,
                    "silent" => opts.silent = true,
                    "fail-on-error" => opts.fail_on_error = true,
                    "version" => opts.version = true,
                    "stdin" => opts.stdin = true,
                    "help" => opts.help = true,
                    key => {
                        // Try to consume next arg as value
                        if i + 1 < args.len() && !args[i + 1].starts_with('-') {
                            let val = &args[i + 1];
                            match key {
                                "transform" => opts.transform = val.clone(),
                                "cpus" => opts.cpus = val.parse().ok(),
                                "verbose" => opts.verbose = val.parse().unwrap_or(0),
                                "extensions" => opts.extensions = Some(val.clone()),
                                "ignore-pattern" => opts.ignore_pattern.push(val.clone()),
                                "ignore-config" => opts.ignore_config.push(val.clone()),
                                "parser" => opts.parser = val.clone(),
                                "parser-config" => opts.parser_config = Some(PathBuf::from(val)),
                                _ => {
                                    if !is_known_long(key) {
                                        extras.push((key.to_string(), val.clone()));
                                    }
                                }
                            }
                            i += 1;
                        } else if !is_known_long(key) {
                            extras.push((key.to_string(), "true".to_string()));
                        }
                    }
                }
            }
        } else if arg.starts_with('-') && arg.len() > 1 && !arg.starts_with("--") {
            // Short options: -t, -c, -v, -d, -p, -s, -h
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut j = 0;
            while j < chars.len() {
                let ch = chars[j];
                match ch {
                    't' => {
                        if j + 1 < chars.len() {
                            opts.transform = chars[j + 1..].iter().collect::<String>();
                            break;
                        } else if i + 1 < args.len() {
                            i += 1;
                            opts.transform = args[i].clone();
                        }
                    }
                    'c' => {
                        if j + 1 < chars.len() {
                            opts.cpus = chars[j + 1..].iter().collect::<String>().parse().ok();
                            break;
                        } else if i + 1 < args.len() {
                            i += 1;
                            opts.cpus = args[i].parse().ok();
                        }
                    }
                    'v' => {
                        if j + 1 < chars.len() {
                            opts.verbose = chars[j + 1..].iter().collect::<String>().parse().unwrap_or(0);
                            break;
                        } else if i + 1 < args.len() {
                            i += 1;
                            opts.verbose = args[i].parse().unwrap_or(0);
                        }
                    }
                    'd' => opts.dry = true,
                    'p' => opts.print = true,
                    's' => opts.silent = true,
                    'h' => opts.help = true,
                    _ => {}
                }
                j += 1;
            }
        } else {
            // Positional: file or directory
            opts.files.push(args[i].clone());
        }

        i += 1;
    }

    if opts.files.is_empty() {
        opts.files.push(".".to_string());
    }

    (opts, extras)
}

/// Returns the extra options collected during parse.
pub fn collect_extra_options() -> Vec<(String, String)> {
    let (_, extras) = parse();
