}", "new_str": "function run(data) {
  const files = data.files;
  const options = data.options || {};
  if (!files || !files.length) {
    finish();
    return;
  }
  async.each(
    files,
    function(file, callback) {
      fs.readFile(file, function(err, source) {
        if (err) {
          updateStatus('error', file, 'File error: ' + err);
          callback();
          return;
        }
        source = source.toString();
        try {
          const j = prepareJscodeshift(options);
          const out = transform(
            {
              path: file,
              source: source,
            },
            {
              j: j,
              jscodeshift: j,
              stats: options.dry ? stats : empty,
              report: function(msg) { report(file, msg); },
            },
            options
          );
          // Handle both sync and async transform results
          const handleResult = function(out) {
            if (!out || out === source) {
              updateStatus(out ? 'nochange' : 'skip', file);
              callback();
              return;
            }
            if (options.print) {
              notify({action: 'print', data: out});
            }
            if (!options.dry) {
              writeFileAtomic(file, out, function(err) {
                if (err) {
                  updateStatus('error', file, 'File writer error: ' + err);
                } else {
                  updateStatus('ok', file);
                }
                callback();
              });
            } else {
              updateStatus('ok', file);
              callback();
            }
          };
          if (out && typeof out.then === 'function') {
            out.then(handleResult, function(err) {
              updateStatus(
                'error',
                file,
                'Transformation error ('+ err.message.replace(/\n/g, ' ') + ')\n' + trimStackTrace(err.stack)
              );
              callback();
            });
          } else {
            handleResult(out);
          }
        } catch(err) {
          updateStatus(
            'error',
            file,
            'Transformation error ('+ err.message.replace(/\n/g, ' ') + ')\n' + trimStackTrace(err.stack)
          );
          callback();
        }
      });
    },
    function(err) {
      if (err) {
        updateStatus('error', '', 'This should never be shown!');
      }
      free();
    }
  );
}"}

