const async = require('neo-async');
const fs = require('graceful-fs');
const getParser = require('./src/getParser');
const jscodeshift = require('./src/core');
const readline = require('readline');

let transform;
let parserFromTransform;

function notify(data) {
  process.stdout.write(JSON.stringify(data) + '\n');
}

function prepareJscodeshift(options) {
  const parser = parserFromTransform ||
    getParser(options.parser, options.parserConfig);
  return jscodeshift.withParser(parser);
}

function updateStatus(status, file, msg) {
  msg = msg ? file + ' ' + msg : file;
  notify({action: 'status', status: status, msg: msg});
}

function free() {
  notify({action: 'free'});
}

// Load transform
const module = require('/tmp/test-jscodeshift/transform.js');
transform = typeof module.default === 'function' ? module.default : module;

// Simulate a batch
const data = {files: ['/tmp/test-jscodeshift/test.js'], options: {parser: 'babel', dry: true, print: true}};

async.each(data.files, function(file, callback) {
  fs.readFile(file, function(err, source) {
    if (err) { console.error('read error:', err); callback(); return; }
    source = source.toString();
    console.error('SOURCE:', JSON.stringify(source));
    try {
      const j = prepareJscodeshift(data.options);
      const out = transform({path: file, source: source}, {j: j, jscodeshift: j}, data.options);
      console.error('OUT:', JSON.stringify(out));
      console.error('SAME:', out === source);
      if (!out || out === source) {
        updateStatus(out ? 'nochange' : 'skip', file);
      } else {
        updateStatus('ok', file);
      }
      callback();
    } catch(err) {
      console.error('ERR:', err);
      updateStatus('error', file, err.message);
      callback();
    }
  });
