export default function transformer(file, api) {
  const j = api.jscodeshift;
  const root = j(file.source);

  // Replace all identifiers named 'foo' with 'bar'
  root.find(j.Identifier, { name: 'foo' })
    .forEach(path => {
      path.node.name = 'bar';
    });

  // Replace all string literals 'hello' with 'hi'
  root.find(j.Literal, { value: 'hello' })
    .forEach(path => {
      path.node.value = 'hi';
    });

  return root.toSource();
}
END
